$base = "C:\Users\PC\Downloads\Ferdi\4TH_YR\DEV\v15.5\2nd-repo-for-hrms-backend-\other files\session\zoom"
foreach ($f in @("1791748216328_ujgf7.messages.json","1791812870880_u3n2g.messages.json")) {
  $p = Join-Path $base $f
  $j = Get-Content $p -Raw | ConvertFrom-Json
  Write-Output "===== $f : $($j.messages.Count) messages ====="
  $i = 0
  foreach ($m in $j.messages) {
    $i++
    if ($m.role -eq "user") {
      foreach ($c in $m.content) {
        if ($c.type -eq "text" -and $c.text -like "*user_input*") {
          $t = $c.text -replace '<user_input mode="act">','' -replace '</user_input>','' -replace '\s+',' '
          Write-Output ("[{0}] {1}" -f $i, $t)
        }
      }
    }
  }
}

