13: /*                              the Join-link button (mock links).      */
14: /*  - signature ok          -> lazy-loads @zoom/meetingsdk, embeds the */
15: /*                              live meeting in this box.              */
16: /* ------------------------------------------------------------------ */
17: 
18: export type ZoomEmbedState =
