// Drives /zoom-embed.html exactly as ZoomEmbeddedMeeting.tsx does:
// boot -> ready handshake -> postMessage zoom-join -> observe outcome.
export default async function run(page, ui) {
  const fixture = JSON.parse(
    await (await import('node:fs/promises')).readFile(
      'C:/Users/PC/AppData/Local/Temp/opencode/zoom-fixture.json',
      'utf8',
    ),
  );

  // Stand in for the host page: record every postMessage the iframe sends back.
  await page.addInitScript(() => {
    window.__msgs = [];
    const orig = window.parent.postMessage?.bind(window.parent);
    // The embed page calls parent.postMessage — from a top-level page that is
    // window.postMessage, so intercept that.
    window.addEventListener('message', (ev) => {
      window.__msgs.push(ev.data);
    });
  });

  await page.goto('http://localhost:5173/zoom-embed.html?t=' + Date.now(), {
    waitUntil: 'domcontentloaded',
  });

  // --- 1. did the SDK globals actually attach? ---
  const boot = await page.evaluate(() => {
    const NS = window.ReactWidgets || window.ZoomMtgEmbedded || window.ZoomMtg;
    return {
      react: typeof window.React,
      reactVersion: window.React && window.React.version,
      reactDom: typeof window.ReactDOM,
      sdkNamespace: NS ? Object.keys(NS).slice(0, 8) : null,
      createClient: NS ? typeof NS.createClient : 'no-namespace',
      zoomErrText: (document.getElementById('zoom-err') || {}).textContent || '',
      zoomErrShown: (document.getElementById('zoom-err') || {}).style?.display,
      zoomRootExists: !!document.getElementById('zoom-root'),
      bootFlag: window.__zoomEmbedBoot,
    };
  });

  // --- 2. can we create a client? this is where ReactCurrentOwner used to die ---
  let clientProbe;
  try {
    clientProbe = await page.evaluate(() => {
      const NS = window.ReactWidgets || window.ZoomMtgEmbedded || window.ZoomMtg;
      const c = NS.createClient();
      return {
        created: !!c,
        methods: ['init', 'join', 'leaveMeeting', 'getMediaStream', 'setViewType']
          .filter((m) => typeof c[m] === 'function'),
        on: typeof c.on,
      };
    });
  } catch (e) {
    clientProbe = { error: String(e && e.message ? e.message : e) };
  }

  // --- 3. send the join message the host app would send ---
  await page.evaluate((f) => {
    window.postMessage(
      {
        type: 'zoom-join',
        sdkKey: f.sdkKey,
        signature: f.signature,
        meetingNumber: f.meetingNumber,
        password: f.password,
        userName: f.userName,
        startVideo: false,
      },
      '*',
    );
  }, fixture);

  // give init+join time to resolve or reject
  await page.waitForTimeout(25000);

  const outcome = await page.evaluate(() => {
    const err = document.getElementById('zoom-err');
    const root = document.getElementById('zoom-root');
    return {
      errorShown: err ? err.style.display === 'block' : false,
      errorText: err ? err.textContent.trim() : '',
      // did the SDK actually render anything into the root?
      rootChildCount: root ? root.children.length : -1,
      rootHtmlLen: root ? root.innerHTML.length : -1,
      rootClass: root ? root.className : '',
      hasCanvas: !!root && !!root.querySelector('canvas'),
      renderedText: root ? root.innerText.slice(0, 400) : '',
    };
  });

  return { boot, clientProbe, outcome };
}

// Step-by-step: watch the three vendored scripts actually execute.
export default async function run(page, ui) {
  const marks = [];

  await page.addInitScript(() => {
    window.__probe = { scripts: [], errors: [] };
    window.addEventListener('error', (e) =>
      window.__probe.errors.push('error: ' + e.message),
    );
  });

  const t0 = Date.now();
  await page.goto('http://localhost:5173/zoom-embed.html?t=' + Date.now(), {
    waitUntil: 'commit',
  });
  marks.push({ at: Date.now() - t0, stage: 'commit' });

  // Poll for the globals rather than assuming domcontentloaded implies them.
  for (let i = 0; i < 12; i++) {
    const snap = await page.evaluate(() => ({
      readyState: document.readyState,
      react: typeof window.React,
      reactDom: typeof window.ReactDOM,
      widgets: typeof window.ReactWidgets,
      scripts: Array.from(document.querySelectorAll('script')).map((s) => ({
        src: s.getAttribute('src'),
        loaded: !!s.dataset,
      })),
      errors: (window.__probe && window.__probe.errors) || [],
    }));
    marks.push({ at: Date.now() - t0, ...snap });
    if (snap.widgets !== 'undefined') break;
    await page.waitForTimeout(5000);
  }

  const final = await page.evaluate(() => ({
    readyState: document.readyState,
    react: typeof window.React,
    reactVersion: window.React && window.React.version,
    reactDom: typeof window.ReactDOM,
    reactDomHasCreateRoot:
      window.ReactDOM && typeof window.ReactDOM.createRoot === 'function',
    widgets: typeof window.ReactWidgets,
    createClient:
      window.ReactWidgets && typeof window.ReactWidgets.createClient,
    widgetKeys: window.ReactWidgets ? Object.keys(window.ReactWidgets).slice(0, 10) : null,
    bootFlag: window.__zoomEmbedBoot,
    errText: (document.getElementById('zoom-err') || {}).textContent,
    errDisplay: (document.getElementById('zoom-err') || {}).style?.display,
  }));

  return { marks, final };
}

