    title: document.title,
    rootChildren: (document.getElementById('root') || {}).childElementCount,
    bodyChars: document.body.innerText.length,
    bodyHead: document.body.innerText.slice(0, 200),
    hasReactDevtools: typeof window.__REACT_DEVTOOLS_GLOBAL_HOOK__,
  }));

  // B. A page with zero app code — pure inline JS.
  await page.setContent(
    '<html><body><div id="x">no</div>' +
      '<script>window.__ran = "YES"; document.getElementById("x").textContent="JS RAN";</script>' +
      '</body></html>',
  );
  out.control = await page.evaluate(() => ({
    inlineFlag: window.__ran || null,
    domText: document.getElementById('x').textContent,
  }));

  // C. External classic script from the dev server, no app involved.
  await page.goto('http://localhost:5173/zoom-embed.html', {
    waitUntil: 'load',
    timeout: 60000,
  });
  out.external = await page.evaluate(async () => {
    const before = typeof window.React;
    await new Promise((res) => {
      const s = document.createElement('script');
      s.src = '/zoom-sdk/react.production.min.js';
      s.onload = res;
      s.onerror = res;
      document.head.appendChild(s);
      setTimeout(res, 15000);
    });
    return { reactBefore: before, reactAfter: typeof window.React };
  });

  return out;
}

