    log.style.display = 'none';
    document.addEventListener('DOMContentLoaded', () => document.body.appendChild(log));
    window.addEventListener('message', (ev) => {
      try {
        log.textContent += JSON.stringify(ev.data) + '\n';
      } catch {}
    });
  });

  await page.goto('http://localhost:5173/zoom-embed.html?t=' + Date.now(), {
    waitUntil: 'load',
    timeout: 60000,
  });
  await page.waitForTimeout(3000);

  // Ask the MAIN world to describe itself by writing into the DOM.
  const mainWorld = await page.evaluate(() => {
    const NS = window.ReactWidgets || window.ZoomMtgEmbedded || window.ZoomMtg;
    let client = null;
    let clientErr = null;
    try {
      client = NS && NS.createClient ? NS.createClient() : null;
    } catch (e) {
      clientErr = String(e && e.message ? e.message : e);
    }
    return {
      react: typeof window.React,
      reactVersion: window.React && window.React.version,
      reactDom: typeof window.ReactDOM,
      nsName: NS ? (window.ReactWidgets ? 'ReactWidgets' : 'other') : null,
      createClient: NS ? typeof NS.createClient : 'no-namespace',
      clientCreated: !!client,
      clientErr,
      clientMethods: client
        ? ['init', 'join', 'leaveMeeting', 'getMediaStream', 'setViewType', 'on'].filter(
            (m) => typeof client[m] === 'function',
          )
        : null,
      bootFlag: window.__zoomEmbedBoot,
    };
  });

  const booted = mainWorld.createClient === 'function' && mainWorld.clientCreated;
  if (!booted) {
    return { verdict: 'SDK DID NOT BOOT', mainWorld };
  }

  // Send the join message the host app sends.
  await page.evaluate((f) => {
    window.postMessage(
      {
        type: 'zoom-join',
        sdkKey: f.sdkKey,
        signature: f.signature,
        meetingNumber: f.meetingNumber,
        password: f.password,
        userName: f.userName,
        startVideo: false,
      },
      '*',
    );
  }, fixture);

  await page.waitForTimeout(30000);

  // Everything below is DOM-based, so it reflects the MAIN world.
  const dom = await page.evaluate(() => {
    const log = document.getElementById('__log');
    const err = document.getElementById('zoom-err');
    const root = document.getElementById('zoom-root');
    return {
      messages: (log?.textContent || '').trim().split('\n').filter(Boolean),
      errorShown: err ? err.style.display === 'block' : false,
      errorText: (err?.textContent || '').trim(),
      rootChildCount: root ? root.children.length : -1,
      rootHtmlLen: root ? root.innerHTML.length : -1,
      rootText: root ? root.innerText.slice(0, 500) : '',
      rootHtmlHead: root ? root.innerHTML.slice(0, 600) : '',
    };
  });

  return { verdict: 'SDK BOOTED, join attempted', mainWorld, dom };
}

