  await page.addInitScript(() => {
    const log = document.createElement('pre');
    log.id = '__log';
    log.style.display = 'none';
    (document.documentElement || document).appendChild(log);
    window.addEventListener('message', (ev) => {
      try {
        log.textContent +=
          JSON.stringify(ev.data).slice(0, 300) + '\n';
      } catch {}
    });
  });

  const net = [];
  page.on('request', (r) => {
    const u = r.url();
    if (/zoom|wasm|webrtc|turn|stun/i.test(u)) net.push('REQ  ' + u.slice(0, 150));
  });
  page.on('response', (r) => {
    const u = r.url();
    if (/zoom|wasm|webrtc|turn|stun/i.test(u))
      net.push('RESP ' + r.status() + ' ' + u.slice(0, 150));
  });
  page.on('requestfailed', (r) => {
    const u = r.url();
    if (/zoom|wasm|webrtc|turn|stun/i.test(u))
      net.push('FAIL ' + (r.failure()?.errorText || '') + ' ' + u.slice(0, 150));
  });

  await page.goto('http://localhost:5173/zoom-embed.html?t=' + Date.now(), {
    waitUntil: 'load',
    timeout: 60000,
  });
  await page.waitForTimeout(2000);

  await page.addScriptTag({
    content: `window.postMessage(${JSON.stringify({
      type: 'zoom-join',
      sdkKey: fixture.sdkKey,
      signature: fixture.signature,
      meetingNumber: fixture.meetingNumber,
      password: fixture.password,
      userName: fixture.userName,
      startVideo: false,
    })}, '*');`,
  });

  await page.waitForTimeout(75000);

  const dom = await page.evaluate(() => {
    const log = document.getElementById('__log');
    const err = document.getElementById('zoom-err');
    const root = document.getElementById('zoom-root');
    return {
      postMessages: (log?.textContent || '').trim().split('\n').filter(Boolean),
      errorShown: err ? err.style.display === 'block' : false,
      errorText: (err?.textContent || '').trim(),
      rootHtmlLen: root ? root.innerHTML.length : -1,
      rootText: root ? root.innerText.slice(0, 800) : '',
      rootHtmlHead: root ? root.innerHTML.slice(0, 1500) : '',
      hasVideo: root ? !!root.querySelector('video') : false,
      videoCount: root ? root.querySelectorAll('video').length : -1,
      buttonLabels: root
        ? Array.from(root.querySelectorAll('button'))
            .map((b) => b.getAttribute('aria-label') || b.innerText.trim())
            .filter(Boolean)
            .slice(0, 25)
        : [],
    };
  });

  return { dom, net: net.slice(0, 60), netCount: net.length };
}

