// Join the real meeting and leave the UI on screen for a screenshot.
export default async function run(page, ui) {
  const { readFile } = await import('node:fs/promises');
  const fixture = JSON.parse(
    await readFile('C:/Users/PC/AppData/Local/Temp/opencode/zoom-fixture.json', 'utf8'),
  );

  await page.setViewportSize({ width: 1280, height: 720 });
  await page.goto('http://localhost:5173/zoom-embed.html?t=' + Date.now(), {
    waitUntil: 'load',
    timeout: 60000,
  });

  // Realistic host-page wrapper, mirroring the HRMS popup layout.
  await page.addScriptTag({
    content: `
      document.body.style.background = '#0b0f19';
      document.getElementById('zoom-root').style.width = '1280px';
      document.getElementById('zoom-root').style.height = '720px';
      window.postMessage(${JSON.stringify({
        type: 'zoom-join',
        sdkKey: fixture.sdkKey,
        signature: fixture.signature,
        meetingNumber: fixture.meetingNumber,
        password: fixture.password,
        userName: fixture.userName,
        startVideo: false,
      })}, '*');
    `,
  });

  // Wait for the embed page to confirm the join.
  await page
    .waitForFunction(
      () => {
        const err = document.getElementById('zoom-err');
        if (err && err.style.display === 'block') return true;
        const root = document.getElementById('zoom-root');
        return !!root && root.innerHTML.length > 5000;
      },
      { timeout: 120000 },
    )
    .catch(() => {});

  await page.waitForTimeout(12000);

  return await page.evaluate(() => {
    const err = document.getElementById('zoom-err');
    const root = document.getElementById('zoom-root');
    return {
      errorText: err && err.style.display === 'block' ? err.textContent.trim() : null,
      renderedLen: root ? root.innerHTML.length : 0,
      participantText: root ? root.innerText.slice(0, 200) : '',
      toolbarButtons: root
        ? Array.from(root.querySelectorAll('button'))
            .map((b) => b.getAttribute('aria-label') || b.getAttribute('title'))
            .filter(Boolean).slice(0, 20)
        : [],
    };
  });
}

