// Prove the restored Content Templates list scrolls when long and stays
// compact when short — using the app's real compiled Tailwind CSS.
export default async function run(page, ui) {
  await page.goto('http://localhost:5173/__tmp-templates.html', {
    waitUntil: 'load',
    timeout: 60000,
  });

  // Build the exact DOM the restored palette renders: capped, scrollable list
  // inside a flex column card.
  const build = async (count) => {
    await page.evaluate((n) => {
      const rows = Array.from(
        { length: n },
        (_, i) =>
          `<button class="w-full rounded-md border border-border px-2 py-1.5 text-left text-[0.68rem]">
             <span class="block truncate font-medium">Front Desk Associate ${i + 1}</span>
             <span class="block truncate text-[0.62rem] text-muted-foreground">Front Office</span>
           </button>`,
      ).join('');
      document.getElementById('stage').innerHTML = `
        <div class="flex h-full flex-col border-border/70" style="border:1px solid #ccc;max-width:220px">
          <div class="flex h-full flex-col p-3">
            <div class="space-y-1.5">
              <div class="rounded-md border px-2 py-1.5 text-[0.7rem]">Job Title</div>
              <div class="rounded-md border px-2 py-1.5 text-[0.7rem]">Job Info</div>
            </div>
            <div class="mt-4 flex min-h-0 flex-1 flex-col border-t pt-3" style="border-color:#ddd">
              <span class="eyebrow font-bold">Content Templates</span>
              <div class="mt-3 flex min-h-0 flex-1 flex-col space-y-3">
                <div class="relative"><input class="h-7 pl-7 text-xs w-full" placeholder="Search templates..." /></div>
                <div id="list" class="max-h-64 min-h-0 flex-1 space-y-3 overflow-y-auto pr-1">${rows}</div>
              </div>
            </div>
          </div>
        </div>`;
    }, count);
    await page.waitForTimeout(300);
    return page.evaluate(() => {
      const el = document.getElementById('list');
      const cs = getComputedStyle(el);
      return {
        items: el.children.length,
        scrollHeight: el.scrollHeight,
        clientHeight: el.clientHeight,
        contentHeight: Math.round(el.getBoundingClientRect().height),
        overflows: el.scrollHeight > el.clientHeight,
        maxHeight: cs.maxHeight,
        overflowY: cs.overflowY,
      };
    });
  };

  const few = await build(3);
  const many = await build(24);

  return { few, many };
}

